() => {
  // Find the modal dialog and its scrollable content area
  const candidates = Array.from(document.querySelectorAll('div')).filter(d => {
    const st = getComputedStyle(d);
    return (st.overflowY === 'auto' || st.overflowY === 'scroll') && d.scrollHeight > d.clientHeight + 10;
  });
  return candidates.map(d => ({
    cls: (d.className || '').toString().slice(0, 120),
    scrollHeight: d.scrollHeight,
    clientHeight: d.clientHeight,
    scrollTop: d.scrollTop
  }));
}

() => {
  const el = Array.from(document.querySelectorAll('div')).find(d => (d.className||'').toString().includes('flex-1 overflow-y-auto px-6 py-5'));
  if (!el) return { ok: false };
  el.scrollTop = 900;
  const st = getComputedStyle(el);
  // check markdown elements inside modal
  const tables = el.querySelectorAll('table').length;
  const codes = el.querySelectorAll('pre, code').length;
  const lists = el.querySelectorAll('ul, ol').length;
  const h2s = el.querySelectorAll('h2').length;
  return { ok: true, scrollTop: el.scrollTop, tables, codes, lists, h2s };
}

() => {
  const el = Array.from(document.querySelectorAll('div')).find(d => (d.className||'').toString().includes('flex-1 overflow-y-auto px-6 py-5'));
  const table = el.querySelector('table');
  table.scrollIntoView({ block: 'center' });
  return { scrollTop: el.scrollTop };
}
